    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            color = src[r][c]
            if color in (main, other) or (r, c) in seen:
                continue
            stack, cells = [(r, c)], []
            seen.add((r, c))
            while stack:
                a, b = stack.pop()
                cells.append((a, b))
                for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na, nb = a+da, b+db
                    if 0 <= na < h and 0 <= nb < w and (na, nb) not in seen and src[na][nb] == color:
                        seen.add((na, nb))
                        stack.append((na, nb))
            objects.append((min(a for a,b in cells), min(b for a,b in cells), color, cells))
    squares = [o for o in objects if len(o[3]) == 4]
    key_row = min(o[0] for o in squares)
    key = sorted((o for o in squares if o[0] == key_row), key=lambda o:o[1])
    pattern = [key[0][2], key[0][2], key[1][2]]
    target = next(o[2] for o in squares if o[0] != key_row)
    starts = sorted((r,c) for r,c,color,cells in objects if len(cells)==1 and c==0)
    for r,c,color,cells in objects:
        for a,b in cells:
            out[a][b] = main
    for sr,sc in starts:
        src[sr][sc] = other
        r,c,direction,pos = sr,sc,0,0
        while 0 <= r < h and 0 <= c < w:
            dr,dc = ((0,1),(-1,0))[direction]
            painted = False
            lr,lc = r,c
            while 0 <= r < h and 0 <= c < w and src[r][c] == other:
                out[r][c] = pattern[pos % 3]
                pos += 1
                painted = True
                lr,lc = r,c
                r,c = r+dr,c+dc
            if not painted:
                break
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = target
            direction = 1-direction
            dr,dc = ((0,1),(-1,0))[direction]
            r,c = lr+dr,lc+dc
    return out
